CREATE OR REPLACE FUNCTION public.enforce_organizer_id_verification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'published'
     AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM 'published') THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = NEW.organizer_id AND p.is_id_verified IS TRUE
    ) THEN
      RAISE EXCEPTION 'ID_VERIFICATION_REQUIRED: complete identity verification before publishing an event.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_event_slug()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  base_slug TEXT;
  short_id  TEXT;
BEGIN
  short_id  := REPLACE(SUBSTRING(NEW.id::text, 1, 8), '-', '');
  base_slug := LOWER(
    TRIM(BOTH '-' FROM
      REGEXP_REPLACE(
        REGEXP_REPLACE(
          REPLACE(LOWER(COALESCE(NEW.title, 'event')), ' ', '-'),
          '[^a-z0-9-]', '', 'g'
        ),
        '-+', '-', 'g'
      )
    )
  );
  NEW.slug := COALESCE(NULLIF(base_slug, ''), 'event') || '-' || short_id;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_profile_role()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Block non-service callers from CHANGING a role on UPDATE.
  IF TG_OP = 'UPDATE' AND NEW.role IS DISTINCT FROM OLD.role THEN
    IF auth.role() IN ('authenticated', 'anon') THEN
      RAISE EXCEPTION 'Unauthorized: Role modification is prohibited.';
    END IF;
  END IF;

  -- Block non-service callers from SELF-ASSIGNING a privileged role on INSERT.
  IF TG_OP = 'INSERT' AND NEW.role IN ('admin', 'staff') THEN
    IF auth.role() IN ('authenticated', 'anon') THEN
      RAISE EXCEPTION 'Unauthorized: Cannot self-assign a privileged role.';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_pass_serial()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.serial := 'TKT-' || TO_CHAR(NOW(), 'YYYY') || '-' || LPAD(nextval('event_pass_serial_seq')::text, 5, '0');
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_enquiry_viewed_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.viewed_at IS NOT NULL AND OLD.viewed_at IS NULL AND NEW.status = 'submitted' THEN
    NEW.status = 'viewed';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_event_ticket_price()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_event_id UUID;
  v_min_price NUMERIC;
BEGIN
  -- Determine which event ID to update based on operation type
  IF TG_OP = 'DELETE' THEN
    v_event_id := OLD.event_id;
  ELSE
    v_event_id := NEW.event_id;
  END IF;

  -- Calculate the minimum price among ticket types for this event
  SELECT MIN(price) INTO v_min_price
  FROM ticket_types
  WHERE event_id = v_event_id;

  -- Default to 0 if there are no ticket types
  IF v_min_price IS NULL THEN
    v_min_price := 0;
  END IF;

  -- Update the parent event's ticket_price column
  UPDATE events
  SET ticket_price = v_min_price
  WHERE id = v_event_id;

  RETURN NULL; -- AFTER triggers can safely return NULL
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$function$
